import { create } from 'zustand';
import { devtools } from 'zustand/middleware';

type ToolExecutionStatus = 'idle' | 'running' | 'success' | 'error';

interface UIStore {
  // Agent tool panel state
  activePanel: 'chat' | 'citations' | 'tools' | 'settings';
  setActivePanel: (panel: UIStore['activePanel']) => void;

  // Tool execution tracking
  toolExecutions: Record<string, { toolName: string; status: ToolExecutionStatus; startedAt: number }>;
  startToolExecution: (executionId: string, toolName: string) => void;
  completeToolExecution: (executionId: string) => void;
  failToolExecution: (executionId: string) => void;

  // Sidebar state
  isSidebarCollapsed: boolean;
  toggleSidebar: () => void;
}

export const useUIStore = create<UIStore>()(
  devtools(
    (set) => ({
      activePanel: 'chat',
      setActivePanel: (panel) => set({ activePanel: panel }),

      toolExecutions: {},
      startToolExecution: (executionId, toolName) =>
        set((state) => ({
          toolExecutions: {
            ...state.toolExecutions,
            [executionId]: { toolName, status: 'running', startedAt: Date.now() },
          },
        })),
      completeToolExecution: (executionId) =>
        set((state) => ({
          toolExecutions: {
            ...state.toolExecutions,
            [executionId]: { ...state.toolExecutions[executionId], status: 'success' },
          },
        })),
      failToolExecution: (executionId) =>
        set((state) => ({
          toolExecutions: {
            ...state.toolExecutions,
            [executionId]: { ...state.toolExecutions[executionId], status: 'error' },
          },
        })),

      isSidebarCollapsed: false,
      toggleSidebar: () => set((state) => ({ isSidebarCollapsed: !state.isSidebarCollapsed })),
    }),
    { name: 'UIStore' } // DevTools identifier
  )
);
